#!/bin/sh
# foothold installer. Generated by the foothold signer; do not edit.
#
#   curl -fsSL <publisher>/install.sh | sh
#   curl -fsSL <publisher>/install.sh | sh -s -- --host-id NAME
#
# Pins the trust anchors below, installs the agent for the account running
# it, schedules it hourly and runs it once.
set -eu
FOOTHOLD_MODE=install

d=$(mktemp -d 2>/dev/null || mktemp -d -t foothold)
trap 'rm -rf "$d"' EXIT
mkdir "$d/trust"

cat >"$d/trust/signer.p256.pem" <<'FOOTHOLD_EOF'
-----BEGIN PUBLIC KEY-----
MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEGc6EmntS16lL9xkz4pyW13r1dzEP
yINjxtCrwZ2w7yAyhyVIxtD3Nj2lyxEyM7ePFgvFx3Szdh3p9zGscA5XDw==
-----END PUBLIC KEY-----
FOOTHOLD_EOF
cat >"$d/trust/signer.ssh.pub" <<'FOOTHOLD_EOF'
ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIKrXu8Ghi5kIhecg+yCsI2D/8n7ci0Zw3N4cREz68zis foothold-signer
FOOTHOLD_EOF
cat >"$d/trust/signer.usign.pub" <<'FOOTHOLD_EOF'
untrusted comment: foothold-signer public key
RWQp8lJpvv8Cm7cLZx+gc4eyLKIyYM6msct1PRoqJSP8gAOHtE2BTHqt
FOOTHOLD_EOF
cat >"$d/trust/recovery.p256.pem" <<'FOOTHOLD_EOF'
-----BEGIN PUBLIC KEY-----
MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEih7OpeTFJO8XFWAN7e+B5kHFXl9s
dhJS00DHa2fh5AiKpHrOh5Vj0lOmxYgo3U40nu9dotEFxMB3SWv0Pe8FTA==
-----END PUBLIC KEY-----
FOOTHOLD_EOF
cat >"$d/trust/recovery.ssh.pub" <<'FOOTHOLD_EOF'
ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIEHP8RAxotVySRWu4FoUOmTY5nvQcet2XWB+5oH2FXrv foothold-recovery
FOOTHOLD_EOF
cat >"$d/trust/recovery.usign.pub" <<'FOOTHOLD_EOF'
untrusted comment: foothold-recovery public key
RWTp7NzQP+U9UuTrz7qBiTxreICp4RS8mY5vu+n91CGIdw4rNaO9Bxvr
FOOTHOLD_EOF
cat >"$d/trust/breakglass.pub" <<'FOOTHOLD_EOF'
ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIEXRV83WRx5o5NVSWD6N5BMk71kx+x8DjwgqK+uLmGSI foothold-breakglass
FOOTHOLD_EOF
cat >"$d/agent.sh" <<'FOOTHOLD_EOF'
#!/bin/sh
# foothold agent: keeps this host's SSH authorized keys in line with a signed
# manifest. POSIX sh only; runs under dash, bash and busybox ash. Assumes only
# sha256sum (or shasum), mktemp, POSIX awk, and one of curl, wget
# or uclient-fetch. Never executes fetched data except a new copy of itself
# whose sha256 the signed bundle names.
#
# Subcommands:
#   run                 fetch, verify, apply (what the scheduler calls)
#   install [opts]      install from an installer's temp dir, schedule, run once
#   schedule            (re)register the scheduler entry, e.g. after an HA reset
#   status              print the last run's status
#   check               validate a bundle body on stdin and print each host's
#                       keys (used by the signer)
#   resolve HOST        print HOST's keys from a bundle body on stdin
#
# Any failure keeps the current keys. Nothing is deleted before its
# replacement is written and checked.

set -u

FOOTHOLD_FORMAT=1
FH_SELF="$0"

# ---------------------------------------------------------------- utilities

fh_now() { date -u +%Y-%m-%dT%H:%M:%SZ; }

log() {
    printf '%s foothold: %s\n' "$(fh_now)" "$*" >&2
    if [ -n "${FH_LOG:-}" ]; then
        printf '%s %s\n' "$(fh_now)" "$*" >>"$FH_LOG" 2>/dev/null || :
    fi
}

die() { log "ERROR: $*"; exit 1; }

have() { command -v "$1" >/dev/null 2>&1; }

sha256_of() {
    if have sha256sum; then
        sha256sum "$1" | awk '{print $1}'
    else
        shasum -a 256 "$1" | awk '{print $1}'
    fi
}

random_byte_pair() {
    _r=$(od -An -N2 -tu2 /dev/urandom 2>/dev/null | tr -d ' \n')
    # no od on OpenWrt
    [ -n "$_r" ] || _r=$(awk -v p="$$" 'BEGIN { srand(); print int(rand() * 65536 + p) % 65536 }')
    echo "$_r"
}

# fetch URL OUT: follows redirects, fails on HTTP errors, bounded runtime.
fetch() {
    rm -f "$2"
    if have curl; then
        curl -fsSL --max-time 60 -o "$2" "$1" 2>/dev/null
    elif have wget; then
        wget -q -T 60 -O "$2" "$1" 2>/dev/null
    elif have uclient-fetch; then
        uclient-fetch -q -T 60 -O "$2" "$1" 2>/dev/null
    else
        log "no fetcher (curl, wget or uclient-fetch) found"
        return 1
    fi
}

# --------------------------------------------------------- manifest parsing
#
# The bundle body, one directive per line; # starts a comment:
#   key   NAME TYPE BLOB [COMMENT...]   (the signer writes these from keys/*.pub)
#   group NAME MEMBER...                (members are keys or other groups)
#   hosts NAME MEMBER...                (members are host IDs or other hosts groups)
#   allow WHO... on WHERE...
#   deny  WHO... on WHERE...
#   trust ROLE FORMAT VALUE             (only honored in recovery-signed bundles)
#
# WHO is keys and groups; WHERE is *, host IDs and hosts groups. A key lands
# on a host if an allow line matches the host and no deny line does. Line
# order doesn't matter.

manifest_awk() {
    # $1 = mode (check|resolve), $2 = host for resolve
    awk -v mode="$1" -v want="${2:-}" '
function err(msg) { print "manifest: " msg | "cat 1>&2"; bad = 1 }
function expand(name, set, depth,    arr, n, i) {
    if (depth > 16) { err("group nesting too deep at " name " (cycle?)"); return }
    if (kind[name] == "k") { set[name] = 1; return }
    if (kind[name] == "g") {
        n = split(gm[name], arr, " ")
        for (i = 1; i <= n; i++) expand(arr[i], set, depth + 1)
        return
    }
    err("undefined key or group: " name)
}
# matches(H, TOKEN): does WHERE token TOKEN cover host H?
function matches(h, t, depth,    arr, n, i) {
    if (t == "*") return 1
    if (depth > 16) { err("hosts nesting too deep at " t " (cycle?)"); return 0 }
    if (t in hg) {
        n = split(hg[t], arr, " ")
        for (i = 1; i <= n; i++) if (matches(h, arr[i], depth + 1)) return 1
        return 0
    }
    return t == h
}
function rule_matches(r, h,    arr, n, i) {
    n = split(rwhere[r], arr, " ")
    for (i = 1; i <= n; i++) if (matches(h, arr[i], 0)) return 1
    return 0
}
# resolve(H): fills got[] with the keys H gets, in key order; returns the count
function resolve(h,    r, arr, n, i, c) {
    split("", allowed); split("", denied); split("", got)
    for (r = 1; r <= nrules; r++) {
        if (!rule_matches(r, h)) continue
        n = split(rwho[r], arr, " ")
        for (i = 1; i <= n; i++) {
            if (rtype[r] == "allow") expand(arr[i], allowed, 0)
            else expand(arr[i], denied, 0)
        }
    }
    c = 0
    for (i = 1; i <= nkeys; i++)
        if ((keys[i] in allowed) && !(keys[i] in denied)) got[++c] = keys[i]
    return c
}
function define(name, k) {
    if (name == "*" || name == "on") { err("line " NR ": " name " is reserved"); return 0 }
    if ((name in kind) || (name in hg)) { err("line " NR ": duplicate name " name); return 0 }
    if (k == "h") hg[name] = ""
    else kind[name] = k
    return 1
}
{ sub(/\r$/, "") }
/^[ \t]*(#|$)/ { next }
{ sub(/[ \t]#.*$/, "") }
$1 == "key" {
    if (NF < 4) { err("line " NR ": key needs NAME TYPE BLOB"); next }
    if ($3 !~ /^(ssh-|ecdsa-|sk-)/) { err("line " NR ": unknown key type " $3); next }
    if ($4 !~ /^[A-Za-z0-9+\/]+=*$/) { err("line " NR ": malformed key blob for " $2); next }
    if (!define($2, "k")) next
    keys[++nkeys] = $2
    l = $3 " " $4
    for (i = 5; i <= NF; i++) l = l " " $i
    keyline[$2] = l
    next
}
$1 == "group" || $1 == "hosts" {
    if (NF < 3) { err("line " NR ": " $1 " needs NAME MEMBER..."); next }
    if (!define($2, $1 == "group" ? "g" : "h")) next
    m = ""
    for (i = 3; i <= NF; i++) m = m " " $i
    if ($1 == "group") gm[$2] = m
    else hg[$2] = m
    next
}
$1 == "allow" || $1 == "deny" {
    on = 0
    for (i = 3; i <= NF; i++) if ($i == "on") { on = i; break }
    if (!on || on == NF) { err("line " NR ": " $1 " needs WHO... on WHERE..."); next }
    nrules++
    rtype[nrules] = $1; rline[nrules] = NR; rwho[nrules] = ""; rwhere[nrules] = ""
    for (i = 2; i < on; i++) rwho[nrules] = rwho[nrules] " " $i
    for (i = on + 1; i <= NF; i++) rwhere[nrules] = rwhere[nrules] " " $i
    next
}
$1 == "trust" { next }
{ err("line " NR ": unknown directive " $1) }
END {
    if (bad) exit 1
    # host IDs: anything a hosts line or a rule names that is not a hosts group
    for (g in hg) {
        n = split(hg[g], arr, " ")
        for (i = 1; i <= n; i++) {
            if (arr[i] == "*") err("hosts " g ": * is not a host")
            else if (arr[i] in kind) err("hosts " g ": " arr[i] " is a key or group, not a host")
            else if (!(arr[i] in hg)) hostid[arr[i]] = 1
        }
    }
    for (r = 1; r <= nrules; r++) {
        n = split(rwhere[r], arr, " ")
        for (i = 1; i <= n; i++)
            if (arr[i] != "*" && !(arr[i] in hg)) hostid[arr[i]] = 1
    }
    for (r = 1; r <= nrules; r++) {
        split("", scratch)
        n = split(rwho[r], arr, " ")
        for (i = 1; i <= n; i++) expand(arr[i], scratch, 0)
    }
    if (bad) exit 1
    if (mode == "check") {
        # every named host, then a host the manifest does not name
        nh = 0
        for (h in hostid) names[++nh] = h
        for (i = 2; i <= nh; i++)
            for (j = i; j > 1 && names[j - 1] > names[j]; j--) { t = names[j]; names[j] = names[j - 1]; names[j - 1] = t }
        names[++nh] = "*"
        for (i = 1; i <= nh; i++) {
            # "\001" matches only `*`: an unnamed host
            c = resolve(names[i] == "*" ? "\001" : names[i])
            if (c == 0) {
                if (names[i] == "*") err("a host not named in the manifest gets no keys (add an `allow ... on *`)")
                else err("host " names[i] " gets no keys")
                continue
            }
            l = names[i]
            for (j = 1; j <= c; j++) l = l " " got[j]
            print l
        }
        exit bad
    }
    c = resolve(want)
    if (bad) exit 1
    for (j = 1; j <= c; j++) print keyline[got[j]]
}
'
}

# ------------------------------------------------------------ configuration

load_config() {
    FH="${FOOTHOLD_HOME:-$(cd "$(dirname "$FH_SELF")" && pwd)}"
    [ -f "$FH/config" ] || die "no config in $FH (not installed?)"
    # shellcheck disable=SC1091
    . "$FH/config"
    : "${HOST_ID:?config lacks HOST_ID}" "${MIRRORS:?config lacks MIRRORS}"
    : "${APPLIER:=file}" "${STALE_DAYS:=7}"
    FH_LOG="$FH/state/log"
    mkdir -p "$FH/state"
}

trim_log() {
    [ -f "$FH_LOG" ] || return 0
    n=$(wc -l <"$FH_LOG")
    if [ "$n" -gt 2000 ]; then
        tail -n 1000 "$FH_LOG" >"$FH_LOG.tmp" && mv -f "$FH_LOG.tmp" "$FH_LOG"
    fi
}

take_lock() {
    if have flock; then
        exec 9>"$FH/state/lock"
        flock -n 9 || { log "another run holds the lock; exiting"; exit 0; }
    fi
}

write_status() {
    # write_status RESULT MESSAGE
    {
        echo "result=$1"
        echo "message=$2"
        echo "time=$(fh_now)"
        echo "host_id=$HOST_ID"
        echo "serial=${B_SERIAL:-}"
        echo "issued=${B_ISSUED:-}"
        echo "signed_by=${B_ROLE:-}"
        echo "format=${B_FORMAT:-}"
        echo "mirror=${B_MIRROR:-}"
        echo "applied_serial=$(cat "$FH/state/serial" 2>/dev/null || echo none)"
        echo "agent_sha256=$(sha256_of "$FH/agent.sh" 2>/dev/null)"
    } >"$FH/state/status.tmp" && mv -f "$FH/state/status.tmp" "$FH/state/status"
    if [ -x "$FH/hooks/report" ]; then
        "$FH/hooks/report" "$FH/state/status" || log "report hook failed"
    fi
}

fail_run() {
    log "ERROR: $*; keeping current keys"
    write_status error "$*"
    exit 1
}

# ------------------------------------------------------------- verification

# verify_role DIR ROLE: succeeds if any signature format this host can check
# verifies DIR/bundle against ROLE's pinned key.
verify_role() {
    _d="$1" _r="$2" _t="$FH/trust"
    if have openssl && [ -s "$_t/$_r.p256.pem" ] && [ -s "$_d/bundle.p256.sig" ]; then
        if openssl base64 -d <"$_d/bundle.p256.sig" >"$_d/p256.der" 2>/dev/null &&
            openssl dgst -sha256 -verify "$_t/$_r.p256.pem" \
                -signature "$_d/p256.der" "$_d/bundle" >/dev/null 2>&1; then
            B_FORMAT=p256
            return 0
        fi
    fi
    if have ssh-keygen && [ -s "$_t/allowed_signers" ] && [ -s "$_d/bundle.sshsig" ]; then
        if ssh-keygen -Y verify -f "$_t/allowed_signers" -I "foothold-$_r" \
            -n foothold -s "$_d/bundle.sshsig" <"$_d/bundle" >/dev/null 2>&1; then
            B_FORMAT=sshsig
            return 0
        fi
    fi
    if have usign && [ -s "$_t/$_r.usign.pub" ] && [ -s "$_d/bundle.usign.sig" ]; then
        if usign -V -q -m "$_d/bundle" -p "$_t/$_r.usign.pub" \
            -x "$_d/bundle.usign.sig" >/dev/null 2>&1; then
            B_FORMAT=usign
            return 0
        fi
    fi
    return 1
}

# fetch_verified WORKDIR: tries each mirror; on success sets B_MIRROR and
# B_ROLE and leaves the verified files in WORKDIR.
fetch_verified() {
    for _m in $MIRRORS; do
        _m="${_m%/}"
        rm -f "$1"/bundle*
        if ! fetch "$_m/bundle" "$1/bundle" || [ ! -s "$1/bundle" ]; then
            log "mirror $_m: no bundle"
            continue
        fi
        for _s in p256.sig sshsig usign.sig; do
            fetch "$_m/bundle.$_s" "$1/bundle.$_s" || rm -f "$1/bundle.$_s"
        done
        for _r in signer recovery; do
            if verify_role "$1" "$_r"; then
                B_MIRROR="$_m" B_ROLE="$_r"
                log "mirror $_m: bundle verified ($B_FORMAT, $_r key)"
                return 0
            fi
        done
        log "mirror $_m: no signature verified against a pinned key"
    done
    return 1
}

bundle_header() { awk -v k="$1" '$0 == "---" { exit } $1 == k { print $2; exit }' "$2"; }
bundle_body() { awk 'found { print } $0 == "---" { found = 1 }' "$1"; }

# --------------------------------------------------------------- trust rotation

# apply_rotation BODYFILE: a recovery-signed bundle may replace the signer's
# pinned keys. Lines, as text so no host needs base64 (OpenWrt has none):
#   trust signer p256  <the PEM body on one line>
#   trust signer ssh   <type> <blob>
#   trust signer usign <the key line of a usign .pub>
apply_rotation() {
    _new="$FH/trust.new"
    rm -rf "$_new" && cp -R "$FH/trust" "$_new" || return 1
    for _fmt in p256 ssh usign; do
        # _v: the key (base64); _t: the ssh key type
        _t=$(awk -v f="$_fmt" '$1 == "trust" && $2 == "signer" && $3 == f { print $4; exit }' "$1")
        [ -n "$_t" ] || continue
        _v="$_t"
        [ "$_fmt" != ssh ] || _v=$(awk '$1 == "trust" && $2 == "signer" && $3 == "ssh" { print $5; exit }' "$1")
        case "$_v" in '' | *[!A-Za-z0-9+/=]*) return 1 ;; esac
        case "$_fmt" in
            p256)
                _file="$_new/signer.p256.pem"
                awk -v b="$_v" 'BEGIN {
                    print "-----BEGIN PUBLIC KEY-----"
                    for (i = 1; i <= length(b); i += 64) print substr(b, i, 64)
                    print "-----END PUBLIC KEY-----" }' >"$_file.tmp"
                ;;
            ssh)
                _file="$_new/signer.ssh.pub"
                case "$_t" in ssh-* | ecdsa-* | sk-*) ;; *) return 1 ;; esac
                printf '%s %s foothold-signer\n' "$_t" "$_v" >"$_file.tmp"
                ;;
            usign)
                _file="$_new/signer.usign.pub"
                printf 'untrusted comment: foothold signer\n%s\n' "$_v" >"$_file.tmp"
                ;;
        esac
        mv -f "$_file.tmp" "$_file" || return 1
        log "rotation: new signer $_fmt key pinned"
    done
    build_allowed_signers "$_new"
    rm -rf "$FH/trust.old" && mv "$FH/trust" "$FH/trust.old" && mv "$_new" "$FH/trust"
}

build_allowed_signers() {
    : >"$1/allowed_signers"
    for _r in signer recovery; do
        if [ -s "$1/$_r.ssh.pub" ]; then
            printf 'foothold-%s %s\n' "$_r" "$(awk '{print $1, $2}' "$1/$_r.ssh.pub")" >>"$1/allowed_signers"
        fi
    done
}

# ------------------------------------------------------------------ appliers

breakglass_blob() { awk '!/^#/ && NF >= 2 { print $2; exit }' "$FH/breakglass.pub"; }

# apply_file KEYSFILE: write TARGET beside itself, check it, then rename.
apply_file() {
    _t="$TARGET"
    _dir=$(dirname "$_t")
    if [ ! -d "$_dir" ]; then
        mkdir -p "$_dir" && chmod 700 "$_dir" || return 1
    fi
    _tmp="$_t.foothold-new"
    {
        echo "# Managed by foothold; rewritten every run. Put local keys in $(basename "$_t").local"
        echo "# foothold: break-glass"
        awk '!/^#/ && NF >= 2' "$FH/breakglass.pub"
        echo "# foothold: manifest (host $HOST_ID)"
        cat "$1"
        if [ -s "$_t.local" ]; then
            echo "# foothold: local ($(basename "$_t").local)"
            cat "$_t.local"
        fi
    } >"$_tmp" || { rm -f "$_tmp"; return 1; }
    if ! grep -qF "$(breakglass_blob)" "$_tmp"; then
        rm -f "$_tmp"
        log "staged file lacks the break-glass key"
        return 1
    fi
    if [ -f "$_t" ] && cmp -s "$_tmp" "$_t"; then
        rm -f "$_tmp"
        log "keys unchanged"
        return 0
    fi
    chmod 600 "$_tmp" && mv -f "$_tmp" "$_t" || { rm -f "$_tmp"; return 1; }
    log "wrote $(grep -c '^[^#]' "$_t") keys to $_t"
}

# EdgeOS keeps keys in config.boot. The agent owns only entries named
# foothold-*; anything else configured by hand is the local drop-in.
VYATTA="${VYATTA_WRAPPER:-/opt/vyatta/sbin/vyatta-cfg-cmd-wrapper}"
CLI_API="${VYATTA_CLI_API:-/bin/cli-shell-api}"

edgeos_name() {
    # stable entry name from the key blob
    printf '%s' "$1" >"$FH/state/blob.tmp"
    echo "foothold-$(sha256_of "$FH/state/blob.tmp" | cut -c1-12)"
}

apply_edgeos() {
    _u="${EDGEOS_USER:-admin}"
    _want="$FH/state/edgeos.want"
    { awk '!/^#/ && NF >= 2 { print $1, $2 }' "$FH/breakglass.pub"; awk '{ print $1, $2 }' "$1"; } >"$_want"
    [ -s "$_want" ] || return 1
    _have=$("$CLI_API" listActiveNodes system login user "$_u" authentication public-keys 2>/dev/null | tr -d "'")
    _ops="$FH/state/edgeos.ops"
    : >"$_ops"
    _names=""
    while read -r _type _blob; do
        _n=$(edgeos_name "$_blob")
        _names="$_names $_n "
        case " $_have " in *" $_n "*) continue ;; esac
        echo "set system login user $_u authentication public-keys $_n type $_type" >>"$_ops"
        echo "set system login user $_u authentication public-keys $_n key $_blob" >>"$_ops"
    done <"$_want"
    for _n in $_have; do
        case "$_n" in foothold-*) ;; *) continue ;; esac
        case "$_names" in *" $_n "*) continue ;; esac
        echo "delete system login user $_u authentication public-keys $_n" >>"$_ops"
    done
    if [ ! -s "$_ops" ]; then
        log "keys unchanged"
        return 0
    fi
    "$VYATTA" begin || return 1
    while read -r _op; do
        # shellcheck disable=SC2086
        if ! "$VYATTA" $_op; then
            "$VYATTA" end
            return 1
        fi
    done <"$_ops"
    if "$VYATTA" commit && "$VYATTA" save; then
        "$VYATTA" end
        log "applied $(wc -l <"$_ops") config changes for $_u"
        return 0
    fi
    "$VYATTA" end
    return 1
}

# -------------------------------------------------------------------- run

self_update() {
    # self_update WORKDIR WANTED_SHA
    [ -z "${FOOTHOLD_UPDATED:-}" ] || fail_run "agent still differs from the signed hash after updating"
    log "agent differs from the signed hash; updating"
    fetch "$B_MIRROR/agent.sh" "$1/agent.sh" || fail_run "could not fetch agent.sh"
    [ "$(sha256_of "$1/agent.sh")" = "$2" ] || fail_run "fetched agent.sh does not match the signed hash"
    sh -n "$1/agent.sh" || fail_run "fetched agent.sh does not parse"
    cp -f "$FH/agent.sh" "$FH/agent.sh.prev" 2>/dev/null
    cp "$1/agent.sh" "$FH/agent.sh.new" && chmod 755 "$FH/agent.sh.new" &&
        mv -f "$FH/agent.sh.new" "$FH/agent.sh" || fail_run "could not replace agent.sh"
    rm -rf "$1"
    exec 9>&-
    FOOTHOLD_UPDATED=1 exec sh "$FH/agent.sh" run
}

cmd_run() {
    load_config
    trim_log
    take_lock
    _w=$(mktemp -d "$FH/state/run.XXXXXX") || die "mktemp failed"
    trap 'rm -rf "$_w"' EXIT

    fetch_verified "$_w" || fail_run "no mirror served a bundle that verifies"

    _b="$_w/bundle"
    [ "$(head -n1 "$_b")" = "foothold-bundle $FOOTHOLD_FORMAT" ] || fail_run "unknown bundle format"
    B_SERIAL=$(bundle_header serial "$_b")
    B_ISSUED=$(bundle_header issued "$_b")
    _issued_epoch=$(bundle_header issued-epoch "$_b")
    _agent_sha=$(bundle_header agent-sha256 "$_b")
    case "$B_SERIAL" in '' | *[!0-9]*) fail_run "bad serial" ;; esac
    case "$_issued_epoch" in '' | *[!0-9]*) fail_run "bad issued-epoch" ;; esac

    _last=$(cat "$FH/state/serial" 2>/dev/null || echo 0)
    [ "$B_SERIAL" -ge "$_last" ] || fail_run "serial $B_SERIAL is older than applied $_last (replay?)"

    bundle_body "$_b" >"$_w/body"
    if grep -q '^[ 	]*trust[ 	]' "$_w/body" && [ "$B_ROLE" != recovery ]; then
        fail_run "bundle carries trust changes but is not signed by the recovery key"
    fi

    if [ -n "$_agent_sha" ] && [ -z "${FOOTHOLD_NO_SELF_UPDATE:-}" ] &&
        [ "$(sha256_of "$FH/agent.sh")" != "$_agent_sha" ]; then
        self_update "$_w" "$_agent_sha"
    fi

    manifest_awk resolve "$HOST_ID" <"$_w/body" >"$_w/keys" 2>"$_w/err" ||
        fail_run "manifest did not resolve: $(head -n3 "$_w/err" | tr '\n' ' ')"
    [ -s "$_w/keys" ] || fail_run "manifest gives this host no keys"

    if [ "$B_ROLE" = recovery ] && grep -q '^[ 	]*trust[ 	]' "$_w/body"; then
        apply_rotation "$_w/body" || fail_run "trust rotation failed"
    fi

    case "$APPLIER" in
        file) apply_file "$_w/keys" || fail_run "could not write $TARGET" ;;
        edgeos) apply_edgeos "$_w/keys" || fail_run "EdgeOS commit failed" ;;
        *) fail_run "unknown applier $APPLIER" ;;
    esac

    echo "$B_SERIAL" >"$FH/state/serial.tmp" && mv -f "$FH/state/serial.tmp" "$FH/state/serial"

    _age=$(($(date +%s) - _issued_epoch))
    if [ "$_age" -gt $((STALE_DAYS * 86400)) ]; then
        log "WARNING: bundle is $((_age / 86400)) days old (signer down, or publisher withholding updates?)"
        write_status stale "applied serial $B_SERIAL, but it was issued $((_age / 86400)) days ago"
    else
        write_status ok "applied serial $B_SERIAL"
    fi
    log "ok: serial $B_SERIAL from $B_MIRROR"
}

# ---------------------------------------------------------------- install

detect_platform() {
    _uid=$(id -u)
    _home="${HOME:-/root}"
    if [ -x "${VYATTA_WRAPPER:-/opt/vyatta/sbin/vyatta-cfg-cmd-wrapper}" ]; then
        PLATFORM=edgeos FH=/config/foothold APPLIER=edgeos TARGET="" SCHED=edgeos
        EDGEOS_USER="${USER:-$(id -un)}"
    elif [ -f /etc/openwrt_release ]; then
        PLATFORM=openwrt FH=/etc/foothold APPLIER=file TARGET=/etc/dropbear/authorized_keys SCHED=openwrt
    elif [ "$_uid" = 0 ] && [ -L /root/.ssh ] && [ -d /data/.ssh ]; then
        PLATFORM=ha FH=/data/foothold APPLIER=file TARGET=/data/.ssh/authorized_keys SCHED=periodic
    elif [ -f /etc/synoinfo.conf ]; then
        PLATFORM=dsm FH="$_home/.local/share/foothold" APPLIER=file TARGET="$_home/.ssh/authorized_keys" SCHED=dsm
    else
        PLATFORM=linux APPLIER=file
        if [ "$_uid" = 0 ]; then
            FH=/etc/foothold TARGET=/root/.ssh/authorized_keys
        else
            FH="$_home/.local/share/foothold" TARGET="$_home/.ssh/authorized_keys"
        fi
        if [ -d /etc/dropbear ] && ! have sshd && [ ! -x /usr/sbin/sshd ]; then
            TARGET=/etc/dropbear/authorized_keys
        fi
        if [ "$_uid" = 0 ] && [ -d /etc/periodic/hourly ]; then
            SCHED=periodic
        elif have crontab; then
            SCHED=cron
        elif have systemctl; then
            SCHED=systemd
        else
            SCHED=none
        fi
    fi
}

schedule_cron() {
    _min=$(($(random_byte_pair) % 60))
    _cur="$FH/state/crontab.cur"
    if ! crontab -l >"$_cur" 2>"$_cur.err"; then
        grep -qi 'no crontab' "$_cur.err" || die "crontab -l failed: $(cat "$_cur.err")"
        : >"$_cur"
    fi
    if grep -qF "$FH/agent.sh" "$_cur"; then
        log "cron entry already present"
        return 0
    fi
    { cat "$_cur"; echo "$_min * * * * sh $FH/agent.sh run >/dev/null 2>&1"; } | crontab - ||
        die "could not install crontab"
    log "cron: hourly at minute $_min"
}

schedule_periodic() {
    _p=/etc/periodic/hourly/foothold-agent
    printf '#!/bin/sh\nexec sh %s/agent.sh run >/dev/null 2>&1\n' "$FH" >"$_p" && chmod 755 "$_p" ||
        die "could not write $_p"
    log "periodic: $_p"
    pgrep crond >/dev/null 2>&1 || log "WARNING: crond is not running; nothing will run $_p"
}

schedule_systemd() {
    _min=$(($(random_byte_pair) % 60))
    if [ "$(id -u)" = 0 ]; then
        _ud=/etc/systemd/system _sc=systemctl
    else
        _ud="$HOME/.config/systemd/user" _sc="systemctl --user"
        log "NOTE: user timers need lingering: sudo loginctl enable-linger $(id -un)"
    fi
    mkdir -p "$_ud"
    printf '[Unit]\nDescription=foothold SSH key sync\n\n[Service]\nType=oneshot\nExecStart=/bin/sh %s/agent.sh run\n' \
        "$FH" >"$_ud/foothold.service"
    printf '[Unit]\nDescription=foothold SSH key sync, hourly\n\n[Timer]\nOnCalendar=*-*-* *:%02d:00\nPersistent=true\n\n[Install]\nWantedBy=timers.target\n' \
        "$_min" >"$_ud/foothold.timer"
    # shellcheck disable=SC2086
    $_sc daemon-reload && $_sc enable --now foothold.timer || log "WARNING: could not enable foothold.timer"
    log "systemd: foothold.timer hourly at minute $_min"
}

schedule_openwrt() {
    _ct=/etc/crontabs/root
    _min=$(($(random_byte_pair) % 60))
    mkdir -p /etc/crontabs
    touch "$_ct"
    grep -qF "$FH/agent.sh" "$_ct" || echo "$_min * * * * sh $FH/agent.sh run >/dev/null 2>&1" >>"$_ct"
    grep -qxF "$FH/" /etc/sysupgrade.conf 2>/dev/null || echo "$FH/" >>/etc/sysupgrade.conf
    grep -qxF "$_ct" /etc/sysupgrade.conf 2>/dev/null || echo "$_ct" >>/etc/sysupgrade.conf
    if [ -x /etc/init.d/cron ]; then
        /etc/init.d/cron enable 2>/dev/null
        /etc/init.d/cron restart 2>/dev/null
    fi
    log "openwrt: crontab minute $_min; $FH/ kept across sysupgrade"
}

schedule_edgeos() {
    "$VYATTA" begin &&
        "$VYATTA" set system task-scheduler task foothold executable path "$FH/agent.sh" &&
        "$VYATTA" set system task-scheduler task foothold executable arguments run &&
        "$VYATTA" set system task-scheduler task foothold interval 1h &&
        "$VYATTA" commit && "$VYATTA" save
    _rc=$?
    "$VYATTA" end
    [ "$_rc" = 0 ] || die "could not add the task-scheduler entry"
    log "edgeos: task-scheduler task foothold, hourly"
}

cmd_schedule() {
    case "$SCHED" in
        cron) schedule_cron ;;
        periodic) schedule_periodic ;;
        systemd) schedule_systemd ;;
        openwrt) schedule_openwrt ;;
        edgeos) schedule_edgeos ;;
        dsm)
            log "DSM: add a Task Scheduler task by hand (Control Panel > Task Scheduler >"
            log "  Create > Scheduled Task > User-defined script), user $(id -un), hourly:"
            log "  sh $FH/agent.sh run"
            ;;
        none) log "WARNING: no scheduler found; run 'sh $FH/agent.sh run' some other way" ;;
        *) die "unknown scheduler $SCHED" ;;
    esac
}

# remove_old_foothold: undo the gist-based foothold once the agent works.
remove_old_foothold() {
    _home="${HOME:-/root}"
    rm -f /etc/periodic/hourly/foothold "$_home/.foothold" "$_home/.foothold-new" 2>/dev/null
    if have crontab && crontab -l >"$FH/state/crontab.old" 2>/dev/null; then
        if grep -qF "$_home/.foothold" "$FH/state/crontab.old"; then
            grep -vF "$_home/.foothold" "$FH/state/crontab.old" | crontab - &&
                log "removed the old foothold crontab line"
        fi
    fi
    log "old foothold removed"
}

cmd_install() {
    _src="${FOOTHOLD_SRC:?install runs from the installer}"
    _host_id="" _mirrors="${FOOTHOLD_MIRRORS:-}" _migrate=0 _force_trust=0
    while [ $# -gt 0 ]; do
        case "$1" in
            --host-id) _host_id="$2"; shift 2 ;;
            --mirror) _mirrors="$2 $_mirrors"; shift 2 ;;
            --home) FOOTHOLD_HOME_OVERRIDE="$2"; shift 2 ;;
            --target) TARGET_OVERRIDE="$2"; shift 2 ;;
            --scheduler) SCHED_OVERRIDE="$2"; shift 2 ;;
            --migrate) _migrate=1; shift ;;
            --force-trust) _force_trust=1; shift ;;
            *) die "unknown option $1" ;;
        esac
    done
    detect_platform
    FH="${FOOTHOLD_HOME_OVERRIDE:-$FH}"
    TARGET="${TARGET_OVERRIDE:-$TARGET}"
    SCHED="${SCHED_OVERRIDE:-$SCHED}"
    if [ -z "$_host_id" ]; then
        # default: the short hostname (vm1.home.qerk.be -> vm1)
        _host_id=$(hostname 2>/dev/null || cat /proc/sys/kernel/hostname)
        _host_id="${_host_id%%.*}"
    fi
    case "$_host_id" in '' | *[!A-Za-z0-9._-]*) die "bad host id '$_host_id'" ;; esac
    [ -n "$_mirrors" ] || die "no mirrors"

    log "installing: platform $PLATFORM, home $FH, host id $_host_id, scheduler $SCHED"
    umask 077
    mkdir -p "$FH/state" || die "cannot create $FH"
    if [ -d "$FH/trust" ] && [ "$_force_trust" = 0 ]; then
        log "keeping the trust anchors already pinned in $FH/trust (--force-trust replaces them)"
    else
        rm -rf "$FH/trust" && cp -R "$_src/trust" "$FH/trust" || die "cannot pin trust anchors"
        build_allowed_signers "$FH/trust"
    fi
    [ -f "$FH/breakglass.pub" ] || cp "$_src/trust/breakglass.pub" "$FH/breakglass.pub" ||
        die "cannot install the break-glass key"
    cp "$_src/agent.sh" "$FH/agent.sh.new" && chmod 755 "$FH/agent.sh.new" &&
        mv -f "$FH/agent.sh.new" "$FH/agent.sh" || die "cannot install agent.sh"
    {
        echo "# foothold agent configuration (written by the installer)"
        echo "HOST_ID='$_host_id'"
        echo "MIRRORS='$(echo $_mirrors)'"
        echo "PLATFORM='$PLATFORM'"
        echo "APPLIER='$APPLIER'"
        echo "TARGET='$TARGET'"
        echo "SCHED='$SCHED'"
        [ -z "${EDGEOS_USER:-}" ] || echo "EDGEOS_USER='$EDGEOS_USER'"
    } >"$FH/config"
    chmod 755 "$FH"

    if ! FOOTHOLD_HOME="$FH" sh "$FH/agent.sh" run; then
        log "first run failed; see $FH/state/log"
        [ "$_migrate" = 1 ] && return 1
        log "scheduling anyway, so it retries hourly"
    fi
    FOOTHOLD_HOME="$FH" sh "$FH/agent.sh" schedule || return 1
    if [ "$_migrate" = 1 ]; then
        remove_old_foothold
    fi
    log "installed. Status: $FH/state/status"
}

# ------------------------------------------------------------------- main

case "${1:-}" in
    run) cmd_run ;;
    install) shift; cmd_install "$@" ;;
    schedule) load_config; cmd_schedule ;;
    status) load_config; cat "$FH/state/status" 2>/dev/null || echo "no status yet" ;;
    check) manifest_awk check ;;
    resolve) [ -n "${2:-}" ] || die "usage: resolve HOST"; manifest_awk resolve "$2" ;;
    *)
        echo "usage: agent.sh run|install|schedule|status|check|resolve HOST" >&2
        exit 2
        ;;
esac
FOOTHOLD_EOF
FOOTHOLD_MIRRORS=$(cat <<'FOOTHOLD_EOF'
https://raw.githubusercontent.com/michaelansel/foothold-michaelansel/main
FOOTHOLD_EOF
)

if [ "$FOOTHOLD_MODE" = install ]; then
    FOOTHOLD_SRC="$d" FOOTHOLD_MIRRORS="$FOOTHOLD_MIRRORS" sh "$d/agent.sh" install "$@"
    exit $?
fi

# ---- migration from the gist-based foothold --------------------------------
# This file replaces foothold.sh in the old gist. Old hosts run it hourly in
# place of their copy of foothold.sh. It keeps the old self-update so a fixed
# version still reaches them, then tries to move the host to the agent; if
# that fails it does what the old foothold did, and tries again next hour.
OLD_FOOTHOLD_URL=https://gist.github.com/michaelansel/27a31805c249e8a1df7a78b31149ff9a/raw/foothold.sh
OLD_INSTALL_KEYS_URL=https://gist.githubusercontent.com/michaelansel/8ce0c6205e6608d233c41404cb702aed/raw/install_keys.sh
old_get() {
    if command -v wget >/dev/null 2>&1; then
        wget -O - -q "$1"
    elif command -v curl >/dev/null 2>&1; then
        curl -s -f -L "$1"
    fi
}
if [ "$(id -u)" = 0 ] && [ -d /etc/periodic/hourly ] && [ -f /etc/periodic/hourly/foothold ]; then
    self=/etc/periodic/hourly/foothold
else
    self="${HOME:-/root}/.foothold"
fi
if [ -f "$self" ]; then
    old_get "$OLD_FOOTHOLD_URL" >"$self-new" || :
    if [ -s "$self-new" ] && ! cmp -s "$self" "$self-new"; then
        mv -f "$self-new" "$self" && chmod +x "$self"
        exec sh "$self"
    fi
    rm -f "$self-new"
fi

if FOOTHOLD_SRC="$d" FOOTHOLD_MIRRORS="$FOOTHOLD_MIRRORS" sh "$d/agent.sh" install --migrate; then
    exit 0
fi
echo "foothold: migration failed; running the old key install this hour" >&2
old_get "$OLD_INSTALL_KEYS_URL" | sh
